SELECT country, life_evaluation, explained_by_gdp_per_capita, explained_by_social_support, explained_by_healthy_life_expectancy, explained_by_freedom, explained_by_generosity, explained_by_low_corruption, dystopia_plus_residual 
FROM whr 
WHERE year = 2025 AND country IN ('Finland', 'Denmark', 'Iceland', 'Norway', 'Sweden');

SELECT COUNT(*), COUNT(explained_by_gdp_per_capita) 
FROM whr 
WHERE year = 2025;
